import pathlib,json,hashlib,sys
name=sys.argv[1]; assert name in ['inference','async','interpreter','llvm','crates','package-core','developer-tools'];root=pathlib.Path.cwd();out=root/'.mlf-build/integration-modular'/name;out.mkdir(exist_ok=True)
manifest=root/'libraries'/('mlf-'+name)/'mlf-package.json';m=json.loads(manifest.read_text());pack=lambda xs:''.join(str(len(x))+':'+x for x in xs)
known={'mlf-foundation':'recovery-foundation-crate-O2-metadata-fix','mlf-language-core':'recovery-language-core-crate-O2','mlf-frontend':'recovery-frontend-crate-O2'}
for extra in ['xmlf','inference','async','interpreter','llvm','crates','package-core','developer-tools']:known['mlf-'+extra]='integration-modular/'+extra
modules=[(name,str((manifest.parent/path).resolve())) for name,path in sorted(m['library']['modules'].items())];deps=[str(root/'.mlf-build'/known[n]/'artifact/unit.mlfci') for n in sorted(m['dependencies'])]
for n in sorted(m['dependencies']):assert json.loads((root/'.mlf-build'/(known[n] if known[n].startswith('integration-modular/') else 'integration-modular/'+known[n])/'result.json').read_text())['complete']
fields=['MLF-CRATE-1',m['name']+'/'+m['version']+'/library','','false',pack([pack(pair) for pair in modules]),pack(deps),str(out/'queries'),str(root/'.mlf-build/recovery-foundation-crate-O2-metadata-fix/builtin/unit')]
(out/'queries').mkdir(exist_ok=True);(out/'artifact').mkdir(exist_ok=True);(out/'crate.spec').write_text(pack(fields));(out/'spec-fields.json').write_text(json.dumps(fields,indent=2)+'\n');cmd=[str(root/'.mlf-build/recovery-ghc-O2/bin/emlf'),'--compile-crate',str(out/'crate.spec'),'-o',str(out/'artifact/unit')];(out/'command.json').write_text(json.dumps(cmd,indent=2)+'\n');(out/'run.py').write_text('import subprocess,json\nfrom pathlib import Path\nsubprocess.run(json.loads((Path(__file__).parent/"command.json").read_text()),check=True)\n')
paths=[manifest,*[pathlib.Path(p) for _,p in modules],*[pathlib.Path(p) for p in deps],*[pathlib.Path(p).with_suffix('.mlfco') for p in deps],root/'.mlf-build/recovery-ghc-O2/receipt.json',out/'crate.spec'];hashes={str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in paths};(out/'inputs.before.json').write_text(json.dumps(hashes,indent=2)+'\n');print(json.dumps({'modules':len(modules),'dependencies':sorted(m['dependencies']),'spec_sha256':hashes[str(out/'crate.spec')]}))
